def pattern_matches(A, marker, B):
 seeds={(r,c) for r,row in enumerate(A) for c,v in enumerate(row) if v==marker}
 mr=min(r for r,c in seeds); mc=min(c for r,c in seeds)
 shp={(r-mr,c-mc) for r,c in seeds}
 h=max(r for r,c in shp)+1; w=max(c for r,c in shp)+1
 paint=set(); matches=[]
 for r in range(len(A)-h+1):
  for c in range(len(A[0])-w+1):
   ps={(r+dr,c+dc) for dr,dc in shp}
   if all(A[x][y]==0 for x,y in ps):
    paint |= ps; matches.append((r,c))
 out={(r,c) for r,row in enumerate(B) for c,v in enumerate(row) if v==marker and A[r][c]==0}
 return shp,matches,paint,out
